import Link from "next/link";
import Image from "next/image";
import { orderedVendorImages } from "@/lib/domain/vendor-media";
import "./vendor-dashboard.css";
import { ArrowRight, Building2, Globe2, LockKeyhole, Star } from "lucide-react";
import type { getVendorDashboard } from "@/lib/queries/vendor-dashboard";
import { VendorCompletion } from "./vendor-completion";
import { VendorNumber, VendorReveal, VendorStars } from "./vendor-motion";
export function VendorDashboardView({ dashboard }: { dashboard: NonNullable<Awaited<ReturnType<typeof getVendorDashboard>>> }) {
  const { profile, completion, rating, reviews } = dashboard;
  const photos = orderedVendorImages(profile.vendor_images ?? []).slice(0, 3);
  return <main className="vendor-dashboard ea-consistent-page vendor-account mx-auto max-w-6xl px-5 py-8 sm:px-8 lg:px-10 lg:py-12">
    <header className="vendor-dashboard-header"><div><p className="eyebrow">Vendor Dashboard</p><div className="vendor-dashboard-identity"><span className="vendor-dashboard-avatar grid shrink-0 place-items-center rounded-full bg-wine/10 text-wine">{profile.profile_image_storage_path ? <Image src={`${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/vendor-media/${profile.profile_image_storage_path}`} alt={`${profile.business_name} profile image`} width={64} height={64} sizes="(max-width: 639px) 48px, (max-width: 1199px) 56px, 64px" className="rounded-full object-cover" /> : <Building2 className="size-4" aria-hidden="true" />}</span><h1 className="font-display" dir="auto">{profile.business_name}</h1></div><p className="text-ink-soft">A considered profile. A lasting first impression.</p></div><div className="vendor-dashboard-actions"><Link href="/vendor/preview" className="ea-button ea-button--secondary">Preview profile</Link><Link href="/vendor/profile" className="ea-button ea-button--primary">Edit profile <ArrowRight className="size-4" /></Link></div></header>
    <div className="vendor-publication-summary"><span className="vendor-publication-pill">{profile.is_public ? <Globe2 className="size-4" /> : <LockKeyhole className="size-4" />}{profile.is_public ? "Public · Live" : "Private"}</span><p>{profile.is_public ? "Couples can discover your business in Ever After." : "Shape your profile privately, then share it when you’re ready."}</p><Link href="/vendor/profile#publication" className="ea-text-action">Manage visibility <ArrowRight className="size-3.5" /></Link></div>
    <div className="vendor-dashboard-grid mt-7">
      <VendorReveal className="vendor-dashboard-completion"><VendorCompletion profileId={profile.id} percentage={completion.percentage} nextSteps={completion.nextSteps} imageCount={profile.vendor_images?.length ?? 0} /></VendorReveal>
      <div className="vendor-dashboard-side"><section className="vendor-panel ea-surface vendor-dashboard-preview"><p className="eyebrow">Public profile</p><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><span className="vendor-publication-pill">{profile.is_public ? <Globe2 className="size-4" /> : <LockKeyhole className="size-4" />}{profile.is_public ? "Public · Live" : "Private"}</span><Link href="/vendor/preview" className="ea-button ea-button--secondary">Preview</Link></div><div className="vendor-dashboard-photos">{photos.map(photo => { const url = photo.external_url ?? (photo.storage_path ? `${process.env.NEXT_PUBLIC_SUPABASE_URL}/storage/v1/object/public/vendor-media/${photo.storage_path}` : null); return url ? <div key={photo.id}><Image src={url} alt={photo.alt_text || "Business photo"} fill sizes="(max-width: 639px) 30vw, 130px" className="object-cover" /></div> : null; })}</div>{!photos.length ? <p className="mt-3 text-sm text-ink-soft">No business photos yet.</p> : null}<Link href="/vendor/profile#gallery" className="ea-text-action text-sm">Business photos · {profile.vendor_images?.length ?? 0} <ArrowRight className="size-4" /></Link></section>
      <VendorReveal delay={100}><section className="vendor-panel vendor-rating ea-surface ea-surface--champagne h-full"><p className="eyebrow">Ratings</p>{rating == null ? <div className="vendor-empty-rating"><Star className="size-8 text-gold" strokeWidth={1.2} aria-hidden="true" /><h2 className="font-display text-2xl">A first impression<br />worth sharing.</h2><p>Your first review will appear here.</p></div> : <><h2 className="mt-8 font-display text-6xl"><VendorNumber value={rating} decimals={1} duration={1500} /><span className="ml-2 text-xl text-ink-soft">/ 5</span></h2><div className="mt-4"><VendorStars rating={rating} /></div><p className="mt-3 text-sm text-ink-soft">{reviews.length} public {reviews.length === 1 ? "review" : "reviews"}</p><a href="#recent-reviews" className="ea-text-action mt-8">Read your reviews <ArrowRight className="size-4" /></a></>}</section></VendorReveal></div>
    </div>
    <section id="recent-reviews" className="mt-8"><div className="mb-5 flex flex-wrap items-baseline justify-between gap-2"><h2 className="font-display text-3xl">Recent reviews</h2><span className="text-xs text-ink-soft">Words from your couples</span></div>{reviews.length ? <div className="grid gap-4 md:grid-cols-2">{reviews.slice(0, 4).map((review, index) => { const score = (review.professionalism + review.punctuality + review.service_attitude + review.value_for_money) / 4; return <VendorReveal key={review.id} delay={index * 100} className="vendor-review-reveal"><article className="vendor-panel vendor-review ea-surface h-full"><div className="flex flex-wrap justify-between gap-2"><h3 className="font-semibold" dir="auto">{review.reviewer_display_name}</h3><time className="text-xs text-ink-soft" dateTime={review.created_at}>{new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Jerusalem" }).format(new Date(review.created_at))}</time></div><div className="my-4"><VendorStars rating={score} /></div><p className="whitespace-pre-wrap break-words text-sm leading-7 text-ink-soft" dir="auto">{review.review_text || "Rating shared without a written note."}</p></article></VendorReveal>; })}</div> : <div className="vendor-panel ea-surface ea-surface--tonal text-center"><Star className="mx-auto mb-3 size-5 text-gold" aria-hidden="true" /><p className="font-display text-xl">Good experiences become kind words.</p><p className="mt-2 text-sm text-ink-soft">Reviews from couples will appear here.</p></div>}</section>
  </main>;
}
